package com.shiv.reportplatform.common.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

import java.math.BigDecimal;

/**
 * One line of a report, e.g. ("Q1 Sales", 12500.50, "Revenue").
 * A record is an immutable data carrier: constructor, getters,
 * equals/hashCode/toString are generated by Java.
 * BigDecimal is used for numbers because double has rounding errors.
 */
public record ReportRowDto(
      @NotBlank(message = "label is required") String label ,
      @NotNull(message = "value is required") BigDecimal value,
      String category
) {
}
